package com.tregy.backend.exception;
import com.tregy.backend.dto.response.ApiErrorResponse;import jakarta.servlet.http.HttpServletRequest;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestControllerAdvice public class GlobalExceptionHandler{private final Clock clock;public GlobalExceptionHandler(Clock clock){this.clock=clock;}
 @ExceptionHandler(AuthException.class)ResponseEntity<ApiErrorResponse> auth(AuthException e,HttpServletRequest r){HttpStatus s=switch(e.getCode()){case "INVALID_CREDENTIALS","INVALID_REFRESH_TOKEN","UNAUTHENTICATED"->HttpStatus.UNAUTHORIZED;case "EMAIL_ALREADY_EXISTS","DUPLICATE_EVENT_CONFLICT"->HttpStatus.CONFLICT;case "NOT_FOUND","PROFILE_NOT_FOUND"->HttpStatus.NOT_FOUND;case "FORBIDDEN"->HttpStatus.FORBIDDEN;case "RATE_LIMITED"->HttpStatus.TOO_MANY_REQUESTS;default->HttpStatus.BAD_REQUEST;};ResponseEntity<ApiErrorResponse> response=body(s,e.getCode(),e.getMessage(),r);return s==HttpStatus.TOO_MANY_REQUESTS?ResponseEntity.status(s).header("Retry-After","600").body(response.getBody()):response;}
 @ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){java.util.Map<String,String> fields=new java.util.LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));HttpStatus s=HttpStatus.BAD_REQUEST;return ResponseEntity.badRequest().body(new ApiErrorResponse(Instant.now(clock),s.value(),s.getReasonPhrase(),"VALIDATION_FAILED","Request validation failed",r.getRequestURI(),(String)r.getAttribute(com.tregy.backend.config.RequestIdFilter.ATTRIBUTE),fields));}
 @ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<ApiErrorResponse> conflict(DataIntegrityViolationException e,HttpServletRequest r){return body(HttpStatus.CONFLICT,"CONFLICT","Request conflicts with existing data",r);}
 @ExceptionHandler(org.springframework.orm.ObjectOptimisticLockingFailureException.class)ResponseEntity<ApiErrorResponse> stale(org.springframework.orm.ObjectOptimisticLockingFailureException e,HttpServletRequest r){return body(HttpStatus.CONFLICT,"STALE_WRITE","The data changed since you loaded it. Reload and try again",r);}
 private ResponseEntity<ApiErrorResponse> body(HttpStatus s,String code,String message,HttpServletRequest r){return ResponseEntity.status(s).body(new ApiErrorResponse(Instant.now(clock),s.value(),s.getReasonPhrase(),code,message,r.getRequestURI(),(String)r.getAttribute(com.tregy.backend.config.RequestIdFilter.ATTRIBUTE),null));}}
